import {subjectLink} from './catalog-data.js?v=0.31.0';
import {pathFinancePreview,unmappedFinance,reportFinancialContext} from './finance-ui.js?v=0.31.0';
import {financialExport} from './finance.js?v=0.31.0';
import {directions,priorities,confidence} from './content.js?v=0.31.0';
import {escapeHTML as h,freshState} from './model.js?v=0.31.0';
import {themes,interestForms,analyze,interestStatus,abilityStatus,fictionalState,freshResults,providerReturnsStatus} from './analysis.js?v=0.31.0';
import {careerBriefReport,careerBriefExport} from './career-report.js?v=0.31.0';
import {privateExplorationForReport,careerCandidates} from './exploration.js?v=0.31.0';
import {occupations,occupationById} from './occupation-data.js?v=0.31.0';

const more=body=>`<details class="more-info"><summary>More info</summary><div>${body}</div></details>`;
const input=(label,path,value,{type='text',help='',placeholder='',max=300}={})=>`<div class="field"><label class="label" for="r-${path}">${h(label)}</label><input id="r-${path}" type="${type}" data-result="${path}" value="${h(value)}" ${type==='number'?'step="any"':`maxlength="${max}"`} placeholder="${h(placeholder)}">${help?more(`<p>${h(help)}</p>`):''}</div>`;
const area=(label,path,value,placeholder='')=>`<div class="field"><label class="label" for="r-${path}">${h(label)}</label><textarea id="r-${path}" data-result="${path}" maxlength="2000" placeholder="${h(placeholder)}">${h(value)}</textarea></div>`;
const check=(label,path,value)=>`<label class="check-line"><input type="checkbox" data-result="${path}" ${value?'checked':''}><span>${h(label)}</span></label>`;
const ext=(label,url)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${h(label)} ↗</a>`;
const options=(choices,value)=>choices.map(([id,label])=>`<option value="${id}" ${id===value?'selected':''}>${h(label)}</option>`).join('');
const select=(label,path,value,choices)=>`<div class="field"><label class="label" for="r-${path}">${h(label)}</label><select id="r-${path}" data-result="${path}">${options(choices,value)}</select></div>`;
const title=(eyebrow,heading,description)=>`<div class="page-intro"><div><span class="eyebrow">${eyebrow}</span><h1>${heading}</h1><p class="intro-copy">${description}</p></div><a class="button secondary" href="#/report">View my report ↗</a></div>`;
export const steps=['Interest results','Ability evidence','Your context','Review & explore'];
export function resultsPage(state,step){
  const r=state.results,analysis=analyze(state);
  const sections=[interestEntry,abilityEntry,contextEntry,reviewEntry];
  return `${title('BRING THE PIECES TOGETHER','Your results. Your story.','Add your results. Connect your experiences. Explore what comes next.')}<div class="entry-layout"><div><nav class="entry-steps" aria-label="Results entry steps">${steps.map((s,i)=>`<button data-action="result-step" data-step="${i}" ${step===i?'aria-current="step"':''}><b>${String(i+1).padStart(2,'0')}</b><span>${s}</span></button>`).join('')}</nav><section class="panel entry-panel">${sections[step](state,analysis)}<div class="activity-nav">${step?`<button class="button secondary" data-action="result-step" data-step="${step-1}">← Back</button>`:'<a href="#/overview" class="text-link">Save & leave</a>'}${step<3?`<button class="button" data-action="result-step" data-step="${step+1}">${step===1?'Continue with or without ability scores':'Save & continue'} →</button>`:'<a class="button" href="#/report">Explore my report →</a>'}</div></section></div><aside class="entry-help"><span class="overline">GROW YOUR REPORT</span><h3>Start with what you have.</h3><p>Missing scores do not close doors.</p><a href="#/example" class="text-link">See an example ↗</a>${more('<p>Copy source labels and scores exactly. Blank means unknown. Your entries save in this browser. Export a backup in Data & privacy.</p>')}</aside></div>`;
}
function interestEntry(state){const i=state.results.interest;return `<span class="overline">01 / INTERESTS</span><h2>What activities draw you in?</h2><p class="entry-lead">Bring the six scores exactly as your source shows them. This measures interests; it does not measure ability.</p><details class="disclosure"><summary>Don’t have results yet? Start here.</summary><p>${ext('Official 30-item Mini-IP','https://onetinterestprofiler.org/')} · ${ext('Official 60-item paper form','https://www.onetcenter.org/dl_tools/ipsf/Interest_Profiler.pdf')}</p><p>For the full experience we selected the 60-item Short Form. The public web tool is the 30-item Mini-IP. If a provider report already contains an O*NET profile, use that one administration and confirm its exact form and score representation.</p><p>When you return, record the source and date, choose the exact form and representation, then copy all six values. A provider’s displayed values may be transformed or rounded.</p></details><div class="form-row" style="margin-top:25px">${select('Exact assessment form','interest.form',i.form,interestForms)}${input('Version / edition, if shown','interest.version',i.version)}</div><div class="form-row">${select('What kind of scores are these?','interest.representation',i.representation,[['unknown','Not confirmed'],['raw','Raw totals / paper counts'],['provider-display','Provider-derived displayed values']])}${input('Source reference','interest.source',i.source,{placeholder:'For example: saved results, page 1',help:'Use a report label; no student name or private URL needed.'})}</div><div class="form-row">${input('Date taken','interest.date',i.date,{type:'date'})}${input('Administration reference · optional','interest.origin',i.origin,{placeholder:'For example: school-interest-october',help:'Use the same reference when the same assessment appears in another report.'})}</div><div class="scale-entry"><h3>Record the scale shown by the source.</h3><p>Raw paper counts: 0–10 · raw online Short Form: 0–40 · raw online Mini-IP: 0–20. The public Mini-IP result page may show a derived 0–10 profile; that is a provider display, not paper counts.</p>${more('<p>Enter the possible scale bounds, not your lowest and highest received scores. Only confirmed raw scores on the official form scale can support Fieldguide interest-theme exploration. Do not convert rounded provider displays back into raw totals.</p>')}<div class="form-row">${input('Possible minimum','interest.min',i.min,{type:'number'})}${input('Possible maximum','interest.max',i.max,{type:'number'})}</div></div><fieldset><legend class="label">Six values exactly as this representation shows · leave unknown blank</legend><div class="six-scores">${themes.map(t=>`<div class="score-input" style="--theme:${t.color}"><label for="score-${t.id}"><b>${t.id}</b><span>${t.name}</span></label><input id="score-${t.id}" type="number" step="any" data-result="interest.scores.${t.id}" value="${h(i.scores[t.id])}" aria-label="${t.name} score" placeholder="—"></div>`).join('')}</div></fieldset><details class="disclosure optional-score-fields"><summary>Also record raw totals or provider display values, if your report shows both</summary><p>These optional values remain separate. Fieldguide never calculates one representation from another.</p>${['rawScores','displayScores'].map((key,n)=>`<fieldset><legend class="label">${n?'Provider display values':'Raw totals / paper counts'} · optional</legend><div class="six-scores">${themes.map(t=>`<div class="score-input" style="--theme:${t.color}"><label for="${key}-${t.id}"><b>${t.id}</b><span>${t.name}</span></label><input id="${key}-${t.id}" type="number" step="any" data-result="interest.${key}.${t.id}" value="${h(i[key][t.id])}" aria-label="${t.name} ${n?'display':'raw'} score" placeholder="—"></div>`).join('')}</div></fieldset>`).join('')}</details>${providerReturnEntry(state)}<div class="source-checks">${check('I checked the exact form, six entered values, and scale against the source.','interest.verified',i.verified)}${check('The form, language, and administration were appropriate for the student; uncertain conditions have been reviewed.','interest.suitable',i.suitable)}</div><div id="entry-readiness" class="entry-readiness" role="status">${readiness(i)}</div>`;}
function providerReturnEntry(state){const p=state.results.providerReturns,status=providerReturnsStatus(p);return `<fieldset class="provider-return-entry"><legend class="label">Already have careers returned by your assessment provider?</legend><p>Copy up to five careers exactly as the provider returned them. Fieldguide does not calculate these results, and they stay distinct from its editorial exploration ideas.</p>${Array.from({length:5},(_,slot)=>`<div class="field"><label class="label" for="provider-return-${slot+1}">Provider career ${slot+1} · optional</label><select id="provider-return-${slot+1}" data-result="providerReturns.idSlots.${slot}"><option value="">${slot?'No additional career':'Choose a returned career'}</option>${occupations.map(c=>`<option value="${h(c.id)}" ${p.slots[slot]===c.id?'selected':''} ${p.slots.some((id,n)=>n!==slot&&id===c.id)?'disabled':''}>${h(c.title)}</option>`).join('')}</select></div>`).join('')}<small>Choose up to five. Duplicate selections are removed automatically.</small><div class="form-row">${input('Provider source reference','providerReturns.source',p.source,{placeholder:'For example: saved results page'})}${input('Provider result date','providerReturns.date',p.date,{type:'date'})}</div>${check('I checked these occupations against the provider’s returned list.','providerReturns.verified',p.verified)}<div id="provider-returns-readiness" class="entry-readiness" role="status"><strong>${h(status.label)}</strong>${status.issues.length?`<ul>${status.issues.map(x=>`<li>${h(x)}</li>`).join('')}</ul>`:'<p>These careers are attributed to the provider and remain separate from Fieldguide connections.</p>'}</div></fieldset>`;}
function readiness(i){const s=interestStatus(i);return `<strong>${s.label}</strong>${s.issues.length?`<ul>${s.issues.map(x=>`<li>${h(x)}</li>`).join('')}</ul>`:'<p>The report can use relative interest themes for explained, editorial starting points.</p>'}`;}
function abilityEntry(state){const r=state.results;return `<span class="overline">02 / APTITUDE & ABILITY EVIDENCE</span><h2>What does your report say?</h2><p class="entry-lead">Have a strengths report? You can add it here, or keep going.</p><div class="notice"><div>We keep each result as the original report describes it.</div></div>${r.abilities.map((a,i)=>`<section class="ability-editor"><div class="section-heading"><h3>Result ${i+1}</h3><button class="text-link" data-action="remove-ability" data-index="${i}">Remove</button></div><div class="form-row">${input('Assessment name',`abilities.${i}.instrument`,a.instrument)}${input('Form / version',`abilities.${i}.form`,a.form)}</div><div class="form-row">${input('Source reference',`abilities.${i}.source`,a.source)}${input('Date taken',`abilities.${i}.date`,a.date,{type:'date'})}</div>${input('Administration reference · optional',`abilities.${i}.origin`,a.origin,{help:'Several dimensions from one battery share an administration reference. They are not separate independent tests.'})}${input('Dimension exactly as reported',`abilities.${i}.dimension`,a.dimension,{placeholder:'For example: spatial visualization'})}<div class="form-row">${input('Reported result',`abilities.${i}.value`,a.value,{placeholder:'Number or provider’s original band'})}${select('Original scale',`abilities.${i}.scale`,a.scale,[['band','Provider label / band'],['percentile','Percentile'],['standard','Standard score'],['raw','Raw score']])}</div>${input('Comparison population / norms',`abilities.${i}.norms`,a.norms,{max:600,help:'Required to contextualize percentiles. Leave unknown if the report does not specify it.'})}${input('Reported interval and meaning · optional',`abilities.${i}.interval`,a.interval,{help:'Only copy an interval supplied by the source; do not estimate one.'})}${area('Source interpretation / limitations',`abilities.${i}.interpretation`,a.interpretation,'What does the source say this result supports?')}${check('I checked this result and its scale against the source.',`abilities.${i}.verified`,a.verified)}<p class="field-help" data-ability-status="${i}" role="status">${h(abilityStatus(a))}</p></section>`).join('')}${r.abilities.length<20?'<button class="button secondary" data-action="add-ability">+ Add an ability result</button>':''}<p class="field-help">One row per dimension. Other attributes such as interpersonal style should stay in your context notes, rather than be relabeled as measured cognitive ability.</p>`;}
function contextEntry(state){const r=state.results;return `<span class="overline">03 / YOUR CONTEXT</span><h2>There’s a person behind the profile.</h2><p class="entry-lead">What have you tried? Choose a direction and add your experience.</p>${state.evidence.project?`<div class="context-quote"><small>FROM YOUR EARLIER REFLECTION</small><p>${h(state.evidence.project)}</p><p>${h(state.evidence.reflection)}</p></div>`:''}<h3>A direction you want to include</h3><div class="form-row" style="margin-top:15px">${input('Any subject or major · optional','nomination',r.nomination,{placeholder:'For example: music, law, cognitive science',max:200})}${input('What draws you to it?','nominationReason',r.nominationReason,{max:2000})}</div><h3>Connect a real experience</h3><p class="field-help">Pick a direction you want to talk about.</p>${directions.map(d=>{const c=r.connections[d.id]||{};return `<details class="context-direction"><summary><span class="mini-dot ${d.color}"></span>${d.title}<span>${c.experience?'Added':'Optional'}</span></summary><div class="context-fields">${select('Related experience',`connections.${d.id}.experience`,c.experience||'',[['','Not recorded'],['enjoyed','I tried something related and enjoyed it'],['new','I have little or no experience yet'],['mixed','I tried it and have mixed feelings'],['disliked','I tried it and did not enjoy it']])}${area('Course / project / experience and what you noticed',`connections.${d.id}.notes`,c.notes||'')}${area('Preparation or support I want to investigate',`connections.${d.id}.preparation`,c.preparation||'','A course, prerequisite, skill, or question for a counselor…')}${select('My preference',`connections.${d.id}.choice`,c.choice||'',[['','No preference recorded'],['explore','Keep this in my exploration'],['unsure','I’m still wondering'],['later','Set aside for now']])}</div></details>`;}).join('')}<h3 style="margin-top:30px">What matters in the experience?</h3><p class="field-help">${ext('CareerOneStop Work Values Matcher','https://cloudfront.careeronestop.org/Toolkit/Careers/work-values-matcher-help.aspx')} can help structure a conversation. Preserve its own labels and any ties in your notes. Your Fieldguide priorities remain a separate reflection.</p>${input('Values source · optional','valuesSource',r.valuesSource,{placeholder:'Work Values Matcher / personal reflection'})}${area('Priorities, ties, and tradeoffs in your own words','valuesNotes',r.valuesNotes)}${state.priorities.length?`<p class="data-note"><strong>Your Fieldguide priorities:</strong> ${state.priorities.map(id=>priorities.find(p=>p.id===id)?.title).join(' → ')}</p>`:'<a class="text-link" href="#/activity/priorities">Try the Fieldguide priorities reflection ↗</a>'}`;}
function reviewEntry(state,a){return `<span class="overline">04 / READY WHEN YOU ARE</span><h2>A starting point for your next conversation.</h2><p class="entry-lead">Take a look, then keep exploring.</p><div class="review-stack"><div><span class="review-number">01</span><section><h3>Interest profile</h3>${readiness(state.results.interest)}</section></div><div><span class="review-number">02</span><section><h3>Ability evidence</h3><p>${a.abilities.length?`${a.abilities.length} result dimension${a.abilities.length===1?'':'s'} recorded. They stay separate from interests and from one another.`:'No ability results entered. Interest and experience exploration remain available.'}</p>${a.abilities.map(x=>`<p><strong>${h(x.dimension||'Unnamed dimension')}</strong> · ${h(x.status)}</p>`).join('')}</section></div><div><span class="review-number">03</span><section><h3>Experiences & choices</h3><p>${Object.values(state.results.connections).filter(x=>x.experience).length} direction(s) have experience context. ${state.results.nomination?`You also chose ${h(state.results.nomination)}.`:'You can add any subject you want to investigate.'}</p></section></div></div><div class="data-note">The report uses a small editorial catalog, with visible reasons. It does not reproduce official O*NET career ranking, predict success, or estimate admission chances.</div>`;}

function profileChart(i,status){
 const min=Number(i.min),max=Number(i.max),valid=i.min.trim()!==''&&i.max.trim()!==''&&Number.isFinite(min)&&Number.isFinite(max)&&max>min;
 return `<div class="profile-bars" role="group" aria-label="Six interest scores on their entered scale">${themes.map((t,n)=>{const v=status.values[n],within=valid&&v!==null&&v>=min&&v<=max,w=within?(v-min)/(max-min)*100:0;return `<div class="profile-bar"><div class="bar-label"><span class="theme-letter" style="background:${t.color}">${t.id}</span><div><strong>${t.name}</strong><small>${t.verb}</small></div><b>${v===null?'—':h(v)}</b></div><div class="bar-track"><i style="width:${w}%;background:${t.color}"></i></div>${v!==null&&!within?'<small class="score-warning">Scale needs checking</small>':''}</div>`;}).join('')}</div><div class="chart-axis"><span>${valid?`Scale ${h(i.min)}–${h(i.max)}`:'Scale not recorded'}</span><span>${i.representation==='raw'?'Raw scores as entered':i.representation==='provider-display'?'Provider-derived display · preserved as shown':'Representation not confirmed'}</span></div>`;
}
function constellation(){return `<svg class="report-orbit" viewBox="0 0 340 300" aria-hidden="true"><g fill="none" stroke="#adc19c" opacity=".3"><circle cx="170" cy="150" r="112"/><circle cx="170" cy="150" r="80" stroke-dasharray="3 8"/><path d="M64 188 137 76 246 104 264 217 151 246Z M137 76l14 170 95-142M64 188l200 29"/></g><g fill="#d9e8b5"><circle cx="64" cy="188" r="7"/><circle cx="137" cy="76" r="11"/><circle cx="246" cy="104" r="8"/><circle cx="264" cy="217" r="5"/><circle cx="151" cy="246" r="8"/></g><path d="m174 135 4 12 12 4-12 4-4 12-4-12-12-4 12-4Z" fill="#e8cdb7"/><circle cx="296" cy="74" r="3" fill="#c2b1d1"/><path d="m87 55 2 6 6 2-6 2-2 6-2-6-6-2 6-2Z" fill="#c2b1d1"/></svg>`;}
function studentBrief(state,a){
 const r=state.results,top=a.status.kind==='ready'?a.status.top.map(id=>themes.find(t=>t.id===id)).filter(Boolean):[];
 const experience=Object.entries(r.connections||{}).filter(([,c])=>c.experience==='enjoyed'||c.experience==='mixed').length;
 const unfamiliar=Object.entries(r.connections||{}).filter(([,c])=>c.experience==='new').length;
 const candidates=careerCandidates(state),career=candidates.find(item=>item.selected)||candidates[0];
 const careerNext=career?`${career.career?.title||career.id}: ${career.experiment?.title||'Explore one task'}`:'';
 const next=state.actions[0]?.title||careerNext||a.agenda[0]?.activity||'Choose one small experiment or conversation.';
 const interestText=top.length?`<p>${top.map(t=>`<span class="brief-chip">${h(t.verb)} · ${h(t.name)}</span>`).join('')}</p>`:a.status.kind==='display-only'?'<p>Provider display values are saved as shown; they do not establish raw interest themes.</p>':a.status.kind==='flat'?'<p>Your scores are tied across the scale. Explore broadly; this is not a low-potential result.</p>':'<p>No differentiated raw profile is ready. Start from a choice or experience, and keep unknowns open.</p>';
 return `<section class="student-brief"><div class="student-brief-heading"><span class="overline">YOUR EXPLORATION BRIEF</span><span>Starting points · not a ranking</span></div><div class="student-brief-grid"><div><h2>Activities to notice</h2>${interestText}<small>${h(a.status.label)}</small></div><div><h2>Experiences & choices</h2><p>${experience} related experience${experience===1?'':'s'} with enjoyment or mixed feelings · ${unfamiliar} direction${unfamiliar===1?'':'s'} marked unfamiliar.</p>${r.nomination?`<p>You chose to include <strong>${h(r.nomination)}</strong>.</p>`:'<p>You can nominate any occupation or study direction.</p>'}</div><div><h2>Next useful step</h2><p>${h(next)}</p><small>Try it, notice what you learn, and decide what to explore next.</small></div></div></section>`;
}
function directionReport(d,state,example,index){const c=d.connection,disabled=example?'disabled':'';return `<article class="path-card ${d.color}" id="path-${d.id}"><div class="path-card-top"><span class="overline">${h(d.lane)}</span><span class="path-index">${String(index+1).padStart(2,'0')}</span></div><div class="path-card-body"><h3>${d.title}</h3><p>${d.description}</p><div class="tags">${d.subjects.map(x=>`<a class="tag" href="${subjectLink(x)}">${h(x)} ↗</a>`).join('')}</div><div class="path-reason"><span>WHY IT’S HERE</span><p>${d.evidence.length?d.evidence.map(e=>({interest:'Connects with your interest themes.',experience:'Connects with an experience you described.',choice:'You chose to explore it.'})[e.source]).join(' '):'Something new to try.'}</p></div><details class="evidence-details"><summary>Look at the evidence & college connections</summary>${d.evidence.map(e=>`<div class="ledger-row"><b>${h(e.source)}</b><p>${h(e.label)}</p>${e.source!=='experience'||state.results.includeNotes?`<small>${h(e.reference)}</small>`:'<small>Your personal note is hidden from this report.</small>'}</div>`).join('')}<h4>What the work can involve</h4><p>${d.work}</p><h4>Preparation to investigate</h4><p>${d.preparation}</p>${c.preparation?`<p>${state.results.includeNotes?h(c.preparation):'You added a preparation question. Include personal notes below to show it.'}</p>`:''}<h4>One career to investigate</h4><p>${ext(d.career,`https://www.onetonline.org/link/summary/${d.soc}`)}</p><p>${d.credential}</p><h4>A college question</h4><p>${d.question}</p><p class="mapping-note">Subjects and career examples are editorial connections, not a computed CIP–SOC crosswalk or guaranteed qualification. Check actual college curricula.</p></details>${pathFinancePreview(d.id)}<div class="next-experiment"><small>TRY THE WORK</small><h4>${d.activity}</h4>${more(`<p>${d.detail}</p>`)}<button class="button secondary no-print" data-action="add-direction" data-id="${d.id}" ${disabled}>${state.actions.some(a=>a.id===`direction-${d.id}`)?'Already in my next steps':'Add experiment to my plan'} +</button></div><div class="path-feedback no-print"><label for="choice-${d.id}">How does this feel?</label><select id="choice-${d.id}" data-result="connections.${d.id}.choice" ${disabled}>${options([['','I haven’t decided'],['explore','I want to explore this'],['unsure','I have questions'],['later','Set aside for now']],c.choice||'')}</select><button class="text-link" data-action="move-report" data-id="${d.id}" ${disabled}>Move to the front ↑</button></div></div></article>`;}
export function counselorEvidenceReport(state){
 const a=analyze(state),r=state.results.interest;
 const provider=state.results.providerReturns,providerStatus=providerReturnsStatus(provider);const checks=[['Form',interestForms.find(([id])=>id===r.form)?.[1]||'Not confirmed'],['Representation',({raw:'Raw totals / paper counts','provider-display':'Provider-derived display',unknown:'Not confirmed'})[r.representation]||'Not confirmed'],['Scale',`${r.min||'unknown'}–${r.max||'unknown'}`],['Source / date',`${r.source||'Not recorded'} · ${r.date||'Not recorded'}`],['Readiness',a.status.label],['Verification',r.verified?'Checked against source':'Needs source check'],['Suitability',r.suitable?'Reviewed':'Not confirmed'],['Provider-returned careers',provider.ids.length?provider.ids.map(id=>occupations.find(c=>c.id===id)?.title||id).join(', '):'None recorded'],['Provider return source / date',`${provider.source||'Not recorded'} · ${provider.date||'Not recorded'}`],['Provider return status',providerStatus.label]];
 const directionRows=a.items.filter(d=>d.evidence.length||d.connection.choice||d.connection.experience).map(d=>`<tr><th>${h(d.title)}</th><td>${d.evidence.map((e,i)=>`<p><b>${h(e.source)}</b> · ${h(e.label)} <small>[${h(`${d.id}:${e.source}:${i+1}`)}]</small>${e.source!=='experience'||r.includeNotes?`<br>${h(e.reference)}`:'<br>Personal note omitted by report privacy setting.'}</p>`).join('')||'<p>No supporting evidence recorded.</p>'}<p>Unknown / student response: ${h(d.connection.experience||'No experience response recorded')} · choice ${h(d.connection.choice||'not recorded')}</p></td></tr>`).join('');
 return `<section class="counselor-evidence"><h2>Counselor evidence view</h2><p>Source and representation are recorded below. Fieldguide interest links are editorial and never aptitude findings.</p><table><tbody>${checks.map(([label,value])=>`<tr><th>${h(label)}</th><td>${h(value)}</td></tr>`).join('')}</tbody></table><h3>Direction evidence ledger</h3><table><tbody>${directionRows||'<tr><td colspan="2">No direction evidence recorded. Unknown and skipped answers remain open.</td></tr>'}</tbody></table><p>Flat profile: ${a.status.kind==='flat'?'scores tie across all six areas.':'not recorded as flat.'} · Provider-derived display: ${a.status.kind==='display-only'?'discussion only; no raw scores inferred.':'not reported.'}</p></section>`;
}
export function visualReport(original,example=false,mode='student'){
 const state=example?fictionalState(freshState()):original,a=analyze(state),r=state.results;
 const hasInterest=a.status.kind==='ready',names=a.status.top.map(id=>themes.find(t=>t.id===id).name),experienceCount=Object.values(r.connections).filter(x=>x.experience).length;
 return `<div class="report-heading"><div><span class="eyebrow">${example?'FICTIONAL EXAMPLE':'YOUR EXPLORATION FIELDGUIDE'}</span><h1>${example?'A possible next chapter.':state.profile.nickname?`${h(state.profile.nickname)}’s next chapter.`:'Your next chapter.'}</h1><p>A picture of where you are. A few possibilities for where to go.</p></div><div class="report-tools no-print"><a class="button secondary" href="#/results">${example?'Enter my results':'Edit my results'} ↗</a><button class="button secondary" data-action="print">Print / save PDF</button>${!example?`<a class="button secondary" href="${mode==='counselor'?'#/report':'#/report/counselor'}">${mode==='counselor'?'Student brief':'Counselor evidence view'} ↗</a><button class="button secondary" data-action="export-report">Export report</button>`:''}</div></div>${example?'<div class="notice example"><div><strong>Fictional example — these are not your results.</strong> All scores and experiences below are invented. Your saved answers are not used or changed.</div></div>':''}${studentBrief(state,a)}${!example?careerBriefReport(state,{mode}):''}<section class="report-hero"><div><span class="eyebrow">POSSIBILITY, WITH ROOM TO GROW</span><h2>${hasInterest?'Follow the questions<br>that pull you in.':'You don’t need a perfect<br>profile to begin.'}</h2><p>${hasInterest?`Your entered interests bring ${h(names.join(', '))} activities into view. Let’s connect them with what you’ve tried—and what you’d like to try next.`:'Start with your experiences and curiosity. Add assessment results when you have them, and keep the possibilities open.'}</p><button class="button" data-action="scroll-report">Find a thread to follow ↓</button></div>${constellation()}</section><div class="report-milestones"><div><b>${a.status.values.filter(v=>v!==null).length}<span>/ 6</span></b><p>interest scores entered</p></div><div><b>${experienceCount}</b><p>directions with experience</p></div><div><b>${state.actions.length}</b><p>next steps in your plan</p></div><div><span class="milestone-symbol">✳</span><p>Your choices stay open.</p></div></div><div class="report-section-label"><span>01 / A PICTURE OF YOU</span><a href="#/results" class="text-link no-print">Revisit the evidence ↗</a></div><div class="report-picture"><section class="report-panel interest-panel"><span class="overline">INTERESTS · WHAT YOU LIKE</span><h2>Six ways to get curious.</h2><p>${h(a.status.label)}</p>${profileChart(r.interest,a.status)}${a.status.issues.length?`<div class="data-note">${a.status.issues.map(x=>`<p>${h(x)}</p>`).join('')}</div>`:''}<details class="evidence-details"><summary>Source & interpretation</summary><p>${h(interestForms.find(([id])=>id===r.interest.form)?.[1]||'Form not recorded')} · ${h(r.interest.version||'Version not provided')}</p><p>Representation: ${h(({raw:'Raw totals / paper counts','provider-display':'Provider-derived display',unknown:'Not confirmed'})[r.interest.representation]||'Not confirmed')} · scale ${h(r.interest.min||'unknown')}–${h(r.interest.max||'unknown')}</p><p>${h(r.interest.source||'No source recorded')} · ${h(r.interest.date||'Date not recorded')}</p><p>Interest scores show preferred activities, not ability. Ties remain ties. These six scores are one profile and are not independent confirming tests.</p></details></section><div class="picture-right"><section class="report-panel values-panel"><span class="overline">PRIORITIES · WHAT MATTERS</span><h2>Make room for your values.</h2>${state.priorities.length?`<ol class="values-list">${state.priorities.map(id=>`<li>${priorities.find(p=>p.id===id).title}</li>`).join('')}</ol>`:'<p>No Fieldguide priorities selected yet.</p>'}${r.valuesNotes?`<p class="personal-quote">${r.includeNotes?h(r.valuesNotes):'Values notes recorded. Choose “Include personal notes” to show them.'}</p><small>${h(r.valuesSource||'Personal notes')}</small>`:'<p>What do you want to learn, create, or contribute?</p>'}<a class="text-link no-print" href="#/activity/priorities">Reflect on priorities ↗</a></section><section class="report-panel ability-panel"><span class="overline">ABILITIES · SEPARATE EVIDENCE</span><h2>${a.abilities.length?'What the source reports.':'Room for another piece.'}</h2>${a.abilities.length?a.abilities.map(x=>`<div class="ability-result"><h3>${h(x.dimension||'Unnamed dimension')}</h3><b>${h(x.value||'Not entered')}</b><span>${h(x.scale)} · ${h(x.status)}</span><p>${h(x.instrument)} · ${h(x.form)} · ${h(x.date)}</p><small>Source: ${h(x.source||'Not recorded')}</small><p>Comparison group: ${h(x.norms||'Not supplied')}</p>${x.interval?`<p>Source interval: ${h(x.interval)}</p>`:''}${x.interpretation&&r.includeNotes?`<details><summary>Source interpretation</summary><p>${h(x.interpretation)}</p></details>`:''}</div>`).join(''):'<p>You can add a strengths report later.</p>'}${a.duplicates.length?'<p class="data-note">Some dimensions share an administration reference. They remain part of the same underlying battery; no confirming votes are counted.</p>':''}<p class="ability-footnote">Your interests and strengths each add to the picture.</p></section></div></div><div class="report-section-label" id="report-directions"><span>02 / THREADS TO FOLLOW</span><span>${a.agenda.length} starting points · you can reorder them</span></div><div class="report-section-intro"><h2>Give a possibility a little attention.</h2><p>Choose a direction. Try the work. Notice how it feels.</p>${more('<p>Order reflects your choices and editorial grouping. It is not a best-major ranking. Open the evidence on a card to see why it appeared.</p>')}</div><div class="path-grid">${a.agenda.map((d,i)=>directionReport(d,state,example,i)).join('')}</div>${a.nomination?`<section class="nomination-card"><span class="overline">YOU CHOSE TO EXPLORE</span><h2>${h(a.nomination)}</h2><p>${r.includeNotes?h(a.nominationReason||'Your curiosity is a reason to investigate.'): 'Your own nomination stays visible, independent of the assessment suggestions.'}</p><h4>Your next experiment</h4><p>Inspect one introductory course and one advanced course. Ask someone studying this subject what surprised them, then note whether you want to learn more.</p>${unmappedFinance()}<button class="button secondary no-print" data-action="nomination-plan" ${example?'disabled':''}>Add to my next steps +</button></section>`:''}<details class="other-directions no-print"><summary>Keep exploring · ${a.remaining.length} more directions${a.items.some(x=>x.connection.choice==='later')?' including those set aside':''}</summary><p>These remain available regardless of your scores. Selecting one does not require test support.</p><div class="path-grid">${a.remaining.map((d,i)=>directionReport(d,state,example,i+4)).join('')}</div></details><a class="text-link no-print catalog-link" href="#/directions">Browse and compare the whole collection ↗</a><div class="report-section-label"><span>03 / ONE SMALL NEXT STEP</span><a class="text-link no-print" href="#/plan">Open my plan ↗</a></div><section class="report-next"><div><span class="overline">TRY → NOTICE → REFLECT</span><h2>You don’t have to choose<br>your whole future today.</h2><p>Choose one experiment. Notice what gives you energy, what frustrates you, and what you want to understand better.</p></div><div>${state.actions.length?`<ol>${state.actions.slice(0,5).map(x=>`<li><strong>${h(x.title)}</strong><span>${x.done?'Tried · reflect on what you learned':'Ready to try'}</span></li>`).join('')}</ol>`:'<p>Save an experiment from a direction card, or add a conversation or class you want to try.</p>'}<a class="button no-print" href="#/plan">Make a small plan →</a></div></section>${reportFinancialContext(state)}<details class="counselor-card more-info"><summary>Questions for my counselor</summary><ul><li>Which programs let me explore several of these interests before specializing?</li><li>What first-year courses and later coursework would help me test these ideas?</li><li>What preparation or support could help me try something unfamiliar?</li><li>What would I need beyond a bachelor’s degree for the work I’m imagining?</li></ul></details>${confidence.some(q=>state.confidence[q.id]?.confidence)?`<details class="disclosure"><summary>Confidence & exposure · self-reports, separate from ability</summary>${confidence.map(q=>{const v=state.confidence[q.id]||{};return `<p>${q.title}: ${h(({new:'little experience',some:'some experience',often:'plenty of practice'})[v.exposure]||'experience not recorded')} · ${v.confidence?`${v.confidence}/5 confidence`:'confidence not recorded'}</p>`;}).join('')}</details>`:''}<details class="disclosure method-details"><summary>How this report was made</summary><p>Fieldguide analysis ${a.version}. Appropriate, source-checked, complete six-score O*NET profiles can supply relative interest themes. Themes tied at the highest raw score above the form minimum are connected to this small catalog through explicit editorial rules. This is an editorial interpretation, not an official O*NET career match. Flat, nearly flat, incomplete, or unconfirmed profiles generate no interest-based routing. Exactly equal scores stay tied.</p><p>Your nominated subject, bookmarks, stated experiences, preparation questions, and choices add separate reasons. Ability results remain attributed discussion evidence and do not filter subjects. No official O*NET correlation ranking, CIP–SOC calculation, predictive model, or probability is claimed.</p><p>Career examples link to ${ext('O*NET OnLine','https://www.onetonline.org/')}; connections to majors are editorial and need curriculum review. ${ext('Interest Profiler manual','https://www.onetcenter.org/dl_files/IP_Manual.pdf')} · ${ext('NCES crosswalk guidance','https://nces.ed.gov/ipeds/cipcode/Files/IES2020_CIP_SOC_Crosswalk_508C.pdf')}</p></details>${!example?`<div class="report-privacy no-print">${check('Include personal experience, preparation, values, and nomination notes in this report and its export.','includeNotes',r.includeNotes)}<small>Printing shows the report as displayed. Open evidence panels before printing to include their detail. Your full draft backup always includes all entries.</small></div>`:''}${mode==='counselor'?counselorEvidenceReport(state):''}<div class="report-signoff"><span>✳</span><p>A fieldguide for who you’re becoming.<br><small>Your interests can grow. Your path can change.</small></p></div>`;
}

export function updateResult(state,el){
 const path=el.dataset.result;if(!path)return false;const parts=path.split('.'),r=state.results;
 if(parts.some(x=>['__proto__','constructor','prototype'].includes(x)))return false;
 if(parts[0]==='providerReturns'&&parts[1]==='idSlots'&&parts.length===3){const slot=Number(parts[2]);if(!Number.isInteger(slot)||slot<0||slot>4)return false;const slots=[...r.providerReturns.slots];slots[slot]=occupationById(el.value)?el.value:'';r.providerReturns.slots=slots;r.providerReturns.ids=[...new Set(slots.filter(id=>occupationById(id)))].slice(0,5);r.providerReturns.verified=false;return true;}let target=r;for(const key of parts.slice(0,-1)){target[key]??={};target=target[key];}const key=parts.at(-1);target[key]=el.type==='checkbox'?el.checked:el.multiple?[...el.selectedOptions].map(option=>option.value).slice(0,5):el.value;
 if(parts[0]==='interest'&&!['verified','suitable'].includes(key)){
   r.interest.verified=false;
   if(key==='form'){
     r.interest.scores=Object.fromEntries(themes.map(t=>[t.id,'']));r.interest.rawScores=Object.fromEntries(themes.map(t=>[t.id,'']));r.interest.displayScores=Object.fromEntries(themes.map(t=>[t.id,'']));r.interest.min=el.value==='onet-60-paper'?'0':'';r.interest.max=el.value==='onet-60-paper'?'10':'';r.interest.suitable=false;
   }
 }
 if(parts[0]==='providerReturns'&&key==='ids'){r.providerReturns.ids=[...new Set(r.providerReturns.ids.filter(id=>occupationById(id)))].slice(0,5);r.providerReturns.slots=Array.from({length:5},(_,n)=>r.providerReturns.ids[n]||'');}if(parts[0]==='providerReturns'&&key!=='verified')r.providerReturns.verified=false;
 if(parts[0]==='abilities'&&key!=='verified')r.abilities[Number(parts[1])].verified=false;
 return true;
}
export function newAbility(){return {id:crypto.randomUUID(),instrument:'',form:'',date:'',source:'',origin:'',dimension:'',value:'',scale:'band',norms:'',interval:'',interpretation:'',verified:false};}
export function reportExport(state){
 const a=analyze(state),include=state.results.includeNotes;
 return {financialContext:financialExport(state.finance),application:'Fieldguide',purpose:'Editorial college exploration; no predicted success or admission probability',analysisVersion:a.version,exportedAt:new Date().toISOString(),interestStatus:a.status.label,interest:state.results.interest,providerReturns:{ids:state.results.providerReturns.ids,source:state.results.providerReturns.source,date:state.results.providerReturns.date,verified:state.results.providerReturns.verified},abilities:a.abilities.map(({interpretation,...ability})=>({...ability,...(include?{interpretation}:{})})),careers:careerBriefExport(state),directions:a.items.map(d=>({id:d.id,title:d.title,lane:d.lane,subjects:d.subjects,career:{label:d.career,url:`https://www.onetonline.org/link/summary/${d.soc}`},why:d.evidence.map(e=>({source:e.source,label:e.label,...(e.source!=='experience'||include?{reference:e.reference}:{})})),preparation:d.preparation,...(include?{personalContext:d.connection}:{}),nextExperience:d.detail})),nomination:state.results.nomination,...(include?{nominationReason:state.results.nominationReason,valuesNotes:state.results.valuesNotes,careerContext:privateExplorationForReport(state,true)}:{}),priorities:state.priorities,actions:state.actions.map(({title,done})=>({title,done}))};
}
